import { createHash } from 'node:crypto'
import path from 'node:path'

import { cloudflare } from '@cloudflare/vite-plugin'
import { defineConfig } from 'vite'
import { patchCssModules } from 'vite-css-modules'
import vinext from 'vinext'

// Generated by `vinext init --platform=cloudflare` and kept as written, apart
// from formatting and the `define` block. See docs/decisions/0001.
export default defineConfig({
  plugins: [
    patchCssModules({ exportMode: 'default' }),
    vinext(),
    cloudflare({
      viteEnvironment: {
        name: 'rsc',
        childEnvironments: ['ssr'],
      },
    }),
  ],
  // The deploy workflow passes the commit it is deploying; /api/health reports
  // it so a health check can tell a new deploy from the previous one still
  // serving. Locally it is "local".
  define: {
    __COMMIT_SHA__: JSON.stringify(process.env.COMMIT_SHA ?? 'local'),
  },
  css: {
    modules: {
      generateScopedName(name: string, filename: string) {
        const relativePath = path
          .relative(import.meta.dirname, filename.replace(/\?.*$/, ''))
          .replaceAll('\\', '/')
        return `_${name}_${createHash('sha256').update(relativePath).digest('hex').slice(0, 7)}`
      },
    },
  },
})
